/* ===== TRA CỨU LEVEL TỪ VỰNG ===== */
let _LEX = null;
function getLex() {
  if (_LEX) return _LEX;
  _LEX = new Map();
  LEVELS.forEach((lv, idx) => {
    (LEX_RAW[lv] || "").split("|").forEach((w) => { if (w && !_LEX.has(w)) _LEX.set(w, idx); });
  });
  return _LEX;
}
// Các dạng gốc có thể có của 1 từ (số nhiều, quá khứ, -ing, so sánh...)
function lemmaCandidates(w) {
  const c = [w];
  const add = (x) => { if (x && x.length > 1 && !c.includes(x)) c.push(x); };
  if (w.endsWith("ies")) add(w.slice(0, -3) + "y");
  if (w.endsWith("ves")) { add(w.slice(0, -3) + "f"); add(w.slice(0, -3) + "fe"); }
  if (w.endsWith("es")) add(w.slice(0, -2));
  if (w.endsWith("s")) add(w.slice(0, -1));
  if (w.endsWith("ied")) add(w.slice(0, -3) + "y");
  if (w.endsWith("ed")) { add(w.slice(0, -2)); add(w.slice(0, -1)); if (/(.)\1ed$/.test(w)) add(w.slice(0, -3)); }
  if (w.endsWith("ing")) { add(w.slice(0, -3)); add(w.slice(0, -3) + "e"); if (/(.)\1ing$/.test(w)) add(w.slice(0, -4)); }
  if (w.endsWith("ly")) add(w.slice(0, -2));
  if (w.endsWith("ier") || w.endsWith("iest")) add(w.replace(/ie(r|st)$/, "y"));
  if (w.endsWith("er")) { add(w.slice(0, -2)); add(w.slice(0, -1)); }
  if (w.endsWith("est")) { add(w.slice(0, -3)); add(w.slice(0, -2)); }
  return c;
}
// Level (chỉ số 0–6) của 1 từ/cụm; -1 = không có trong danh sách tham chiếu
function wordLevelIdx(raw) {
  const lex = getLex();
  const w = String(raw || "").toLowerCase().replace(/[’]/g, "'").replace(/[^a-z' \-\.]/g, " ").replace(/\s+/g, " ").trim();
  if (!w) return -1;
  for (const k of lemmaCandidates(w)) if (lex.has(k)) return lex.get(k);
  if (w.includes(" ")) {
    // cụm nhiều từ: lấy level cao nhất trong các từ nội dung đã biết
    let best = -1;
    w.split(" ").forEach((p) => { if (p.length > 2) { for (const k of lemmaCandidates(p)) if (lex.has(k)) { best = Math.max(best, lex.get(k)); break; } } });
    return best;
  }
  return -1;
}
// Level từ vựng đang áp dụng cho worksheet (rỗng = theo level chính)
function effVocabLevels(cfg) {
  const v = (cfg.vocabLevels || []).filter((x) => LEVELS.includes(x));
  return v.length ? LEVELS.filter((x) => v.includes(x)) : [cfg.level];
}
function maxVocabIdx(cfg) {
  return Math.max(...effVocabLevels(cfg).map((x) => LEVELS.indexOf(x)));
}
// Danh sách từ nội dung được phép khi band thấp (Pre A1/A1); "" nếu band cao hơn
function allowedWordsText(cfg) {
  const maxI = maxVocabIdx(cfg);
  if (maxI > 1) return "";
  const allowed = [];
  getLex().forEach((idx, w) => { if (idx <= maxI && !w.includes(" ") && w.length > 1) allowed.push(w); });
  return allowed.sort().join(", ");
}
// Các từ trong 1 đoạn text vượt band từ vựng (chỉ tính từ có trong danh sách tham chiếu)
function findAboveBand(text, maxI) {
  const str = String(text == null ? "" : text);
  const re = /[A-Za-z][A-Za-z'’\-]*/g;
  const out = new Set();
  let m;
  while ((m = re.exec(str))) {
    const tok = m[0].replace(/['’]s$/i, "");
    if (tok.length < 3) continue;
    const prev = str.slice(0, m.index).replace(/\s+$/, "");
    if (/^[A-Z]/.test(tok) && !(prev === "" || /[.!?:\n]$/.test(prev))) continue;
    if (wordLevelIdx(tok) > maxI) out.add(tok.toLowerCase());
  }
  return [...out];
}
// Quy tắc từ vựng đưa vào prompt (kèm danh sách từ được phép khi level thấp)
function vocabRule(cfg) {
  const lvls = effVocabLevels(cfg);
  const maxI = maxVocabIdx(cfg);
  let txt = `TỪ VỰNG: chỉ dùng từ thuộc band ${lvls.join(" + ")} (tham chiếu English Vocabulary Profile; Pre A1 theo wordlist Cambridge Starters). KHÔNG dùng từ vượt ${LEVELS[maxI]}. Quy tắc này ƯU TIÊN HƠN mọi yêu cầu bối cảnh: nếu bối cảnh/chủ đề đòi từ vượt band thì ĐƠN GIẢN HOÁ tình huống (dùng hành động, đồ vật, địa điểm quen thuộc) chứ KHÔNG dùng từ khó.`;
  const al = allowedWordsText(cfg);
  if (al) txt += ` Danh sách từ nội dung ĐƯỢC PHÉP (ngoài ra chỉ thêm từ chức năng, số, tên riêng; nếu bắt buộc dùng từ ngoài danh sách thì tối đa 1–2 từ, dễ đoán): ${al}.`;
  return txt;
}
// Từ khoá chủ điểm theo taxonomy (nếu giáo viên chọn từ gợi ý)
function topicMetaRule(cfg) {
  const m = cfg.topicMeta;
  if (!m || m.en !== cfg.topic) return "";
  return `Chủ điểm theo taxonomy ${m.id}: ${m.en}${m.vi ? " / " + m.vi : ""}. Phạm vi: ${m.scope || "—"}. Ví dụ: ${m.examples || "—"}. Bám đúng phạm vi này, không lan sang chủ điểm khác.`;
}

/* ===== GỢI Ý CHỦ ĐIỂM TỪ TAXONOMY ===== */
function taxSubs(kind, levelNames) {
  const idxs = levelNames.map((x) => LEVELS.indexOf(x)).filter((x) => x >= 0);
  const T = TAXONOMY[kind];
  const topics = Object.fromEntries(T.topics.map((t) => [t[0], { id: t[0], en: t[1], vi: t[2] }]));
  // lọc theo from ≤ level ≤ to với BẤT KỲ level nào được chọn (level cao gồm cả chủ điểm của level thấp còn hiệu lực)
  return T.subs
    .filter((s) => idxs.some((i) => s[6] <= i && i <= s[7]))
    .map((s) => ({ id: s[0], topicId: s[1], topic: topics[s[1]], en: s[2], vi: s[3], scope: s[4], examples: s[5], from: s[6], to: s[7] }));
}

/* ===== QUÉT TỪ VỰNG THEO LEVEL ===== */
function scanWorksheet(ws, cfg) {
  const maxI = maxVocabIdx(cfg);
  const found = new Map(); // word -> {word, levelIdx, where:Set}
  const check = (text, where) => {
    const str = String(text == null ? "" : text).replace(/\*\*|==|___/g, " ");
    const re = /[A-Za-z][A-Za-z'’\-]*/g;
    let m;
    while ((m = re.exec(str))) {
      const tok = m[0].replace(/['’]s$/i, "");
      if (tok.length < 3) continue;
      const prev = str.slice(0, m.index).replace(/\s+$/, "");
      const sentenceStart = prev === "" || /[.!?:\n]$/.test(prev);
      if (/^[A-Z]/.test(tok) && !sentenceStart) continue; // tên riêng giữa câu
      const lv = wordLevelIdx(tok);
      if (lv > maxI) {
        const key = tok.toLowerCase();
        if (!found.has(key)) found.set(key, { word: key, levelIdx: lv, where: new Set() });
        found.get(key).where.add(where);
      }
    }
  };
  const learn = ws.learn || {};
  (learn.vocab || []).forEach((v) => check(v.word, "Từ vựng trọng tâm"));
  grammarBlocks(learn.grammar).forEach((b) => {
    if (b.kind === "table") { (b.headers || []).forEach((h) => check(h, "Language Focus")); (b.rows || []).forEach((r) => r.forEach((c) => check(c, "Language Focus"))); }
    else { (b.examples || []).forEach((e) => check(e, "Language Focus")); } // lời giải thích ngữ pháp (metalanguage) không tính vào từ vựng
  });
  (ws.exercises || []).forEach((ex, i) => {
    if (!ex || ex._failed) return;
    const base = "Bài " + (i + 1);
    (ex.wordBox || []).forEach((w) => check(w, base + " · hộp từ"));
    check(ex.passage, base); // instruction/tiêu đề bài (circle, tick, match…) là ngôn ngữ ra lệnh, không quét
    (ex.examples || []).forEach((r) => r.forEach((c) => check(c, base)));
    (ex.items || []).forEach((it, j) => {
      const w = base + " · câu " + (j + 1);
      check(it.prompt, w);
      (it.options || []).forEach((o) => check(o, w));
      check(it.answer, w);
      (it.cells || []).forEach((c) => check(c, w));
    });
  });
  const out = [...found.values()].map((f) => ({ ...f, where: [...f.where] }));
  out.sort((a, b) => b.levelIdx - a.levelIdx || a.word.localeCompare(b.word));
  return out;
}
// Từ vựng trọng tâm có thật sự xuất hiện trong bài tập không?
function unusedVocab(ws) {
  const vocab = (ws.learn && ws.learn.vocab) || [];
  const exs = (ws.exercises || []).filter((e) => e && !e._failed);
  if (!exs.length) return [];
  const text = exs.map((ex) => [ex.passage, ...(ex.examples || []).flat(), ...(ex.items || []).flatMap((it) => [it.prompt, it.answer, ...(it.options || []), ...(it.cells || [])])].join(" ")).join(" ").toLowerCase();
  return vocab.filter((v) => {
    const w = String(v.word || "").toLowerCase().trim();
    if (!w) return false;
    const stem = w.length > 4 ? w.replace(/(ing|ed|es|s|e|y)$/, "") : w;
    return !text.includes(stem);
  }).map((v) => v.word);
}

/* ================= GỌI API CLAUDE ================= */
// Cố gắng vá JSON bị cắt cuối: đóng nốt chuỗi/ngoặc còn thiếu
function repairJson(raw) {
  let s = raw.trim();
  const start = s.indexOf("{");
  if (start > 0) s = s.slice(start);
  // bỏ dấu phẩy thừa trước } hoặc ]
  s = s.replace(/,\s*([}\]])/g, "$1");
  // đếm ngoặc/nháy để đóng nốt nếu bị cắt giữa chừng
  let inStr = false, esc = false;
  const stack = [];
  for (const ch of s) {
    if (esc) { esc = false; continue; }
    if (ch === "\\") { esc = true; continue; }
    if (ch === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (ch === "{" || ch === "[") stack.push(ch);
    else if (ch === "}" || ch === "]") stack.pop();
  }
  if (inStr) s += '"';
  while (stack.length) {
    const open = stack.pop();
    s += open === "{" ? "}" : "]";
  }
  s = s.replace(/,\s*([}\]])/g, "$1");
  return s;
}

function parseLoose(text) {
  const clean = text.replace(/```json|```/g, "").trim();
  const start = clean.indexOf("{");
  const end = clean.lastIndexOf("}");
  const core = end > start ? clean.slice(start, end + 1) : clean.slice(start);
  try { return JSON.parse(core); }
  catch { return JSON.parse(repairJson(core)); }
}

// Lỗi có kèm nhãn để phân biệt: lỗi máy chủ/hạn mức (không phải do nội dung dài)
function ApiError(message, kind, retryable) {
  const e = new Error(message);
  e.kind = kind; e.retryable = !!retryable;
  return e;
}

async function callClaudeRaw(prompt, maxTokens) {
  let res;
  try {
    res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        max_tokens: 1000,
        messages: [{ role: "user", content: prompt }],
      }),
    });
  } catch (netErr) {
    throw ApiError("Không kết nối được máy chủ. Kiểm tra mạng rồi thử lại.", "network", true);
  }

  let data = null;
  try { data = await res.json(); } catch (e) { data = null; }

  // Máy chủ trả lỗi -> báo đúng nguyên nhân thay vì đổ cho "nội dung dài"
  if (!res.ok || (data && data.type === "error")) {
    const msg = (data && data.error && data.error.message) || "";
    const status = res.status;
    if (status === 429 || /rate.?limit|quota|usage limit/i.test(msg)) {
      throw ApiError("Tài khoản đã chạm giới hạn sử dụng (rate limit). Chờ ít phút rồi thử lại, hoặc dùng tài khoản khác.", "rate_limit", true);
    }
    if (status === 529 || status === 503 || /overload/i.test(msg)) {
      throw ApiError("Máy chủ đang quá tải. Chờ một lát rồi bấm Thử lại.", "overloaded", true);
    }
    if (status === 401 || status === 403) {
      throw ApiError("Không có quyền gọi AI (phiên đăng nhập có thể đã hết hạn). Tải lại trang rồi thử lại.", "auth", false);
    }
    throw ApiError("Máy chủ báo lỗi" + (status ? " (" + status + ")" : "") + (msg ? ": " + msg.slice(0, 120) : "") + ".", "server", status >= 500);
  }

  const text = (data && data.content ? data.content : []).filter((b) => b.type === "text").map((b) => b.text).join("\n");
  if (!text.trim()) throw ApiError("Máy chủ trả về nội dung rỗng. Bấm Thử lại nhé.", "empty", true);
  return text;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function callClaude(prompt, maxTokens) {
  // Lỗi máy chủ/hạn mức: chờ rồi thử lại (tối đa 2 lần), KHÔNG đổi prompt.
  // Lỗi JSON hỏng: thử lại 1 lần kèm nhắc trả JSON đầy đủ.
  let lastApiErr = null;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      return parseLoose(await callClaudeRaw(prompt, maxTokens));
    } catch (e) {
      if (e && e.kind) {
        lastApiErr = e;
        if (!e.retryable || attempt === 2) throw e;
        await sleep(1200 * (attempt + 1)); // giãn cách tăng dần
        continue;
      }
      // JSON hỏng -> thử lại một lần với lời nhắc rõ hơn
      try {
        const retryPrompt = prompt + "\n\nLƯU Ý QUAN TRỌNG: chỉ trả JSON HỢP LỆ, ĐẦY ĐỦ (đóng đủ ngoặc), KHÔNG markdown, KHÔNG cắt giữa chừng. Nếu nội dung dài, rút gọn cho vừa nhưng phải đóng đủ JSON.";
        return parseLoose(await callClaudeRaw(retryPrompt, maxTokens));
      } catch (e2) {
        if (e2 && e2.kind) { lastApiErr = e2; if (!e2.retryable || attempt === 2) throw e2; await sleep(1200 * (attempt + 1)); continue; }
        throw e2;
      }
    }
  }
  throw lastApiErr || new Error("Không tạo được nội dung.");
}

